#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int is_leap(int year)
{
    return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *s = argv[1];

    /* length must be exactly 10 */
    if (strlen(s) != 10) {
        puts("INVALID");
        return 0;
    }

    /* hyphens at the right places */
    if (s[4] != '-' || s[7] != '-') {
        puts("INVALID");
        return 0;
    }

    /* all other characters must be digits */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (!isdigit((unsigned char)s[i])) {
            puts("INVALID");
            return 0;
        }
    }

    /* parse numbers */
    int year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
                (s[2] - '0') * 10   + (s[3] - '0');
    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* month range */
    if (month < 1 || month > 12) {
        puts("INVALID");
        return 0;
    }

    /* day range */
    static const int mdays[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };
    int maxday = mdays[month - 1];
    if (month == 2 && is_leap(year))
        maxday = 29;

    if (day < 1 || day > maxday) {
        puts("INVALID");
        return 0;
    }

    puts("VALID");
    return 0;
}
